def norm(data: bytes) -> bytes:
    return data.replace(b"\r\n", b"\n")


def main() -> int:
    here = Path(__file__).resolve().parent
    if not (here / "backend" / "app").is_dir():
        print("This file must sit in the folder that contains your 'backend' folder.")
        print(f"I looked in: {here}")
        return 1

    plan = []
    for rel, blob in FILES.items():
        data = zlib.decompress(base64.b64decode(blob))
        target = here / rel
        state = "NEW" if not target.exists() else ("same" if norm(target.read_bytes()) == data else "UPDATE")
        plan.append((rel, target, data, state))

    todo = [p for p in plan if p[3] != "same"]
    print(f"Project folder: {here}")
    print(f"{len(plan)} files checked: {len(todo)} to write, {len(plan) - len(todo)} already correct.\n")
    for rel, _t, _d, state in todo:
        print(f"  {state:7} {Path(rel)}")
    if not todo:
        print("Nothing to change.")
    elif "--yes" not in sys.argv:
        if input("\nWrite these files now? Replaced files are backed up first. [y/N] ").strip().lower() != "y":
            print("Cancelled. Nothing was changed.")
            return 0

    if todo:
        backup = here / "_backup_before_update" / datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        for rel, target, data, state in todo:
            if state == "UPDATE":
                saved = backup / rel
                saved.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(target, saved)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
            if hashlib.sha256(norm(target.read_bytes())).digest() != hashlib.sha256(data).digest():
                print(f"PROBLEM: {rel} was not written correctly.")
                return 1
        print(f"\nDone. {len(todo)} file(s) written.")

    front = here / "frontend"
    npm = shutil.which("npm")
    if not npm:
        print("\nNode.js was not found. Install Node 18 or newer from nodejs.org, then run:  cd frontend  and  npm install")
        return 0
    if not (front / "node_modules").is_dir():
        if "--yes" in sys.argv or input("\nRun 'npm install' in the frontend folder now? [Y/n] ").strip().lower() in ("", "y"):
            code = subprocess.call([npm, "install", "--no-audit", "--no-fund"], cwd=str(front))
            if code != 0:
                print("npm install failed. Check your internet connection and run it again inside the frontend folder.")
                return code
    print("\nAll set. Start it with:  cd frontend  then  npm run dev   (backend must be running on port 8000)")
    return 0


if __name__ == "__main__":
    sys.exit(main())